SELECT id, 'software_engineer', 'all levels', '[{"name": "Online assessment", "format": "HackerRank, timed", "tests": "Two or three coding problems and about 40 multiple-choice questions on networking, operating systems and databases; usually for early-career candidates", "duration": "70 to 90 minutes"}, {"name": "Recruiter screen", "format": "Call", "tests": "Background, interest in Cisco and role fit, no coding", "duration": "About 30 minutes"}, {"name": "Technical interviews", "format": "Webex, one or two rounds", "tests": "Resume discussion and one medium coding problem; data structures, memory management, networking basics and the OSI model", "duration": "45 to 60 minutes each"}, {"name": "Final loop", "format": "Three to five interviews, sometimes over two days", "tests": "Deeper technical rounds, system design mainly for experienced candidates, and behavioural interviews", "duration": null}]'::jsonb, '["arrays", "networking_basics", "operating_systems_basics", "sql_fundamentals", "behavioural_storytelling"]'::jsonb, 'Cisco does not publish a fixed timeline according to the source; campus hiring often finishes within a few weeks of the assessment.', 'The source describes four to five rounds for most software engineer interviews and says Cisco tests networking and systems fundamentals more than most software companies. It states no year.', NULL, 3, 'The source describes the technical interview as including one medium coding problem.', '[{"url": "https://www.designgurus.io/answers/detail/what-is-the-cisco-interview-process-like-round-by-round", "title": "Cisco interview process, round by round (DesignGurus)"}]'::jsonb, '2026-10-15'
FROM company_profiles WHERE slug = 'cisco';

